previewCss:
.darma-loader-darma-b11-power-pulse { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #4ade80); width: var(--loader-size, 76px); height: var(--loader-size, 76px); display: grid; place-items: center; }
.darma-loader-darma-b11-power-pulse span { position: relative; width: 54%; height: 54%; border: calc(var(--loader-size, 76px) * .08) solid var(--accent); border-radius: 50%; border-top-color: transparent; box-shadow: 0 0 calc(var(--loader-size, 76px) * .16) var(--accent); animation: darma-loader-darma-b11-power-pulse-power calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-darma-b11-power-pulse span::after { content: ''; position: absolute; top: -34%; left: 50%; width: calc(var(--loader-size, 76px) * .08); height: 36%; margin-left: calc(var(--loader-size, 76px) * -.04); background: var(--accent-2); border-radius: 4px; box-shadow: 0 0 calc(var(--loader-size, 76px) * .1) var(--accent-2); }
@keyframes darma-loader-darma-b11-power-pulse-power { 0%, 100% { opacity: .45; box-shadow: 0 0 calc(var(--loader-size, 76px) * .05) var(--accent); } 50% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size, 76px) * .24) var(--accent); } }

